470	-- Single-table views are writable, and writes run as the view owner, bypassing PlatformAccount's RLS.
471	REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.my_accounts FROM anon, authenticated;
472	
473	-- Definer view on purpose: inside a policy, LocalAccess is filtered by its own reader-level select policy, so an inline check can't see partial access.
474	-- Unlike a function, the planner can inline a view, so a policy can check one account without building the whole set.
475	-- Keep DISTINCT and don't add space_id: LocalAccess only shows memberships at reader level, and one row per membership would reveal them.
476	-- security_barrier stops a caller's non-leakproof filter from running below the access join, where it would see accounts of other spaces.
477	CREATE OR REPLACE VIEW public.accounts_in_my_partial_spaces WITH (security_barrier) AS
478	SELECT DISTINCT la.account_id
479	FROM public."SpaceAccess" AS sa
480	    JOIN public.my_user_accounts() AS my (uid) ON (sa.account_uid = my.uid)
481	    JOIN public."LocalAccess" AS la USING (space_id)
482	WHERE sa.permissions >= 'partial';
483	
484	COMMENT ON VIEW public.accounts_in_my_partial_spaces IS 'security utility: the accounts in spaces where I have at least partial access. Used by the PlatformAccount select policy.';
485	
486	-- anon: public access will read authors through the PlatformAccount select policy, which fails without this grant.
487	REVOKE ALL ON public.accounts_in_my_partial_spaces FROM public, anon, authenticated, service_role;
488	GRANT SELECT ON public.accounts_in_my_partial_spaces TO anon, authenticated, service_role;
