509	CREATE OR REPLACE FUNCTION public.accept_group_invitation(token varchar) RETURNS boolean
510	SET search_path = '' SECURITY DEFINER
511	LANGUAGE plpgsql AS $$
512	DECLARE
513	    v_creator UUID;
514	    token_info JSONB;
515	    v_group_id UUID;
516	    auth_uid UUID;
517	    token_type varchar;
518	    as_admin BOOLEAN;
519	    is_admin BOOLEAN;
520	BEGIN
521	    BEGIN
522	        SELECT auth.uid() INTO STRICT auth_uid;
523	        IF auth_uid IS NULL THEN RETURN false; END IF;
524	        SELECT creator INTO v_creator STRICT FROM public.secret_token WHERE id=token;
525	        SELECT public.get_secret_token(token) INTO token_info STRICT;
526	        SELECT (token_info->>'groupId')::UUID, token_info->>'type', (token_info->'admin')::boolean INTO v_group_id, token_type, as_admin STRICT;
527	        IF token_type != 'groupInvitation' THEN RETURN false; END IF;
528	        SELECT admin INTO is_admin FROM public.group_membership WHERE member_id = v_creator AND group_id = v_group_id;
529	        IF is_admin IS NOT true THEN RETURN false; END IF;
530	        INSERT INTO public.group_membership (group_id, member_id, admin) VALUES (v_group_id, auth_uid, as_admin);
531	        RETURN true;
532	    EXCEPTION WHEN OTHERS THEN RETURN false;
533	    END;
534	END;
535	$$;
