export const acceptGroupInvitation = async (
  client: DGSupabaseClient,
  token: string,
): Promise<string | null> => {
  const userData = await getSessionBaseUserData(client);
  if (!userData) return "Not logged in";
  const { data, error } = await client.rpc("accept_group_invitation", {
    token,
  });
  if (error) return error.message || "Unknown error";
  if (!data) return "Unable to accept invitation";
  return null;
};

export const createGroup = async (
  client: DGSupabaseClient,
  name: string,
): Promise<{ groupId: string | null; error: string | null }> => {
  const result = await client.functions.invoke<{ group_id: string }>(
    "create-group",
    { body: { name } },
  );
  if (result.error) {
    let message =
      typeof result.error === "string"
        ? result.error
        : (result.error as { message: string }).message;
    try {
      const body = (await (
        result.error as { context?: Response }
      ).context?.json()) as { msg?: string } | undefined;
      if (body?.msg) message = body.msg;
    } catch {
      // ignore parse errors
    }
    return { groupId: null, error: message };
  }
  return { groupId: result.data?.group_id ?? null, error: null };
};

export const removeFromGroup = async ({
  client,
  groupId,
  memberId,
}: {
  client: DGSupabaseClient;
  groupId: string;
  memberId?: string;
}): Promise<string | null> => {
  if (memberId === undefined) {
    const userData = await getSessionBaseUserData(client);
    memberId = userData?.id ?? undefined;
    if (memberId === undefined) return "Not logged in";
  }
  const response = await client
    .from("group_membership")
    .delete()
    .eq("member_id", memberId)
    .eq("group_id", groupId)
    .select();
  if (response.error) return response.error.message;
  if (response.data === null || response.data.length === 0)
    return "No such record";

  return null; // success
};

export const setGroupAdmin = async ({
  client,
  groupId,
  memberId,
  admin,
}: {
  client: DGSupabaseClient;
  groupId: string;
  memberId: string;
  admin: boolean;
}): Promise<string | null> => {
  const response = await client
    .from("group_membership")
    .update({ admin })
    .eq("member_id", memberId)
    .eq("group_id", groupId)
    .select();
  if (response.error) return response.error.message;
  // The update policy only matches rows the caller administers, so a
  // non-admin caller gets an empty result rather than an error.
  if (response.data === null || response.data.length === 0)
    return "No such member, or you are not an admin of this group";

  return null; // success
};

